import React from 'react';
import { BoldReport } from '../components/BoldReport';

const BoldReportsPage: React.FC = () => {
  return (
    <div>
      <h2>Bold Reports Viewer</h2>
      <BoldReport
        apiUrl="https://localhost:59497/api/reports/event-report" // Your backend API
        reportName="event-report.rdl"                            // RDL file placed in public/
        X-Tenant-ID="22222222-2222-2222-2222-222222222222"       // Replace with actual tenant if needed
      />
    </div>
  );
};

export default BoldReportsPage;
